---@param friendList table[]
function FriendComponent:SetFriendList(friendList)
    self.friendList  = checkTable(friendList)
    self.friendIdMap = {}
    for _, friendData in ipairs(self:GetFriendList()) do
        self.friendIdMap[tostring(friendData.friendId)] = friendData
    end
end

---@return table[]
function FriendComponent:GetFriendList()
    return checkTable(self.friendList)
end

--- 是否是好友
