---@return boolean
function FriendComponent:IsFriend(friendId)
    return self:GetFriendInfo(friendId) ~= nil
end

--- 是否有好友列表数据
---@return boolean
function FriendComponent:HasFriendList()
    return #checkTable(self.friendList) > 0
end

-- 同步最新的好友列表数据
function FriendComponent:SyncFriendList(doneCb)
    local requestData = {}
    GameUtils.Request(Interfaces.FriendList, {}, function(request, response)
        if checkInt(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            local myFriendList = table.filter(checkTable(responseData.friendList), function(k, v)
                return checkNumber(v.friendId) <= 0
            end)
            table.sort(myFriendList, function(a, b)
                return checkInt(a.isOnline) > checkInt(b.isOnline)
            end)
            self:SetFriendList(myFriendList)
        end
        if doneCb then doneCb() end
    end)
end


function FriendComponent:ClearFriendPVPCountDown(friendId)
    friendId = checkString(friendId)
    self.pvpCountdownMap[friendId] = nil
end

function FriendComponent:SetFriendPVPCountDown(friendId)
    friendId = checkString(friendId)
    local cd = self:GetPVPWaitTime()
    local nowTimeStamp = checkInt(TimeZoneUtils.UtcSeconds)
    local endTimeStamp = nowTimeStamp + cd
    self.pvpCountdownMap[friendId] = endTimeStamp
end
--
function FriendComponent:GetFriendPVPCountDown(friendId)
    friendId = checkString(friendId)
    local cd
    if isNull(self.pvpCountdownMap[friendId]) then
        cd = 0
    else
        local nowTimeStamp = checkInt(TimeZoneUtils.UtcSeconds)
        cd = self.pvpCountdownMap[friendId] - nowTimeStamp
    end
    return cd

end

function FriendComponent:IsFriendInPVPCountDown(friendId)
    friendId = checkString(friendId)
    local isInCD
    local cd = self:GetFriendPVPCountDown(friendId)
    isInCD = cd > 0 and true or false
    return isInCD, cd
end

--- 该玩家删除好友
---@param playerId number @ 玩家id
---@param succeedCb fun():void | nil @ 确认删除成功的回调
function FriendComponent:DelFriend(playerId, succeedCb)
    GameUtils.SecondConfirm(localize("是否删除好友？"), function()
        GameUtils.Request(Interfaces.FriendDel, { friendId = checkNumber(playerId) }, function(request, response)
            if checkInt(response.errCode) == 0 then
                for i = 1, #self.friendList do
                    if self.friendList[i].friendId == response.data.friendId then
                        self.friendIdMap[tostring(self.friendList[i].friendId)] = nil
                        table.remove(self.friendList, i)
                        break
                    end
                end
                GameUtils.Toast(localize("删除成功！！！！"))
                -- 清理此好友未读消息
                local social = AppService:GetInstance():GetSocialLine()
                social:ReadUnreadMessage(playerId)
                social:UpdatePrivateChatRedPoint()
                if succeedCb then succeedCb() end
            end
        end)
    end)
end

---请求添加好友
---@param playerId number @ 玩家id
---@param succeedCb fun():void | nil @ 请求成功的回调
function FriendComponent:AddFriend(playerId, succeedCb)
    local isSendAddReq = self:IsSendAddReq(playerId)--好友请求中
    local ownPlayerId = GameUtils.GetPlayerId()
    if checkNumber(ownPlayerId) == checkNumber(playerId) then
        GameUtils.Toast(localize("不能添加自己为好友"))
        return
    end
    if self:GetFriendInfo(playerId) ~= nil then
        GameUtils.Toast(localize("已经是好友了"))
        return
    end
    if not isSendAddReq then
        GameUtils.Request(Interfaces.FriendAddFriend, {friendId = playerId}, function(request, response)
            if checkInt(response.errCode) == 0 then
                self:SendAddFriend(playerId)
                if succeedCb then succeedCb() end
                GameUtils.Toast(localize("好友申请已发送"))
            end
        end)
    else
        GameUtils.Toast(localize("好友申请已发送"))
    end
end

