---领取该朋友送的体力
---@param playerId number 朋友的玩家id
function FriendComponent:DrawGift(playerId, succeedCb)
    local ReqFunc = function(arg)
        GameUtils.Request(
                Interfaces.FriendGift,
                arg,
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        GameUtils.Toast(localize("领取体力成功"))
                        --self.drawFriendIds = {}
                        for i, v in ipairs(response.data.drawFriendIds) do--统一服务端的数据类型--只返回领取的朋友的id
                            table.insert(self.drawFriendIds, checkString(v))
                        end
                        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                        playerComponent.playerDojo.hp = response.data.hpInfo.hp--体力数据维护
                        playerComponent.playerDojo.nextHpSeconds = response.data.hpInfo.lastCdTime--体力恢复时间数据维护
                        UIModule.OpenDialog(--打开通用道具获取的弹窗
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = {
                                        rewards = response.data.rewards
                                    }
                                }
                        )
                        succeedCb(#self.drawFriendIds)
                    end
                end
        )
    end
    local arg = {}
    if not isNull(playerId) then--领取单人
        arg = {
            friendId = playerId
        }
        local maxDrawFriendGift = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 2).num)--好友领取体力次数上限
        if #self.drawFriendIds >= maxDrawFriendGift then
            GameUtils.Toast(localize("已达今日领取上限"))
            return
        end
        if self:IsReceiveGift(playerId) and (not self:IsDrawGift(playerId)) then
            ReqFunc(arg)
        else
            GameUtils.Toast(localize("没有可以领取的体力"))
        end
    else--领取全部
        ReqFunc(arg)
    end
end

