---赠送朋友体力
---@param playerId number @ 朋友的玩家id,不传id一键赠送
---@param succeedCb fun():void @ 赠送成功的回调
function FriendComponent:GiveGift(playerId, succeedCb)
    local ReqFunc = function(arg)
        GameUtils.Request(
                Interfaces.FriendGive,
                arg,
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        --self.giveFriendIds = {}
                        GameUtils.Toast(localize("赠送体力成功"))
                        for i, v in ipairs(response.data.giveFriendIds) do--统一服务端的数据类型--只返回赠送的朋友的id
                            table.insert(self.giveFriendIds, checkString(v))
                        end
                        succeedCb()
                    end
                end
        )
    end
    local arg = {}
    if not isNull(playerId) then--赠送单人
        arg = {
            friendId = playerId
        }
        local maxGiveFriendGift = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 7).num)--好友赠送体力次数上限
        if #self.giveFriendIds >= maxGiveFriendGift then
            GameUtils.Toast(localize("已达今日赠送上限"))
            return
        end
        if not self:IsGiveGift(playerId) then
            ReqFunc(arg)
        else
            GameUtils.Toast(localize("今天已赠送，明天再来"))
        end
    else--领取全部
        ReqFunc(arg)
    end
end

---是否有可以赠送体力的好友
function FriendComponent:HasNotGiveGiftFriend()
    if isNull(self.friendList) then
        return false
    else
        for i = 1, #self.friendList do
            if not self:IsGiveGift(self.friendList[i].friendId) then
               return true
            end
        end
        return false
    end
end

---是否有未领取的体力
function FriendComponent:HasUnclaimedGift()
    if isNull(self.giftList) then
        return false
    else
        for i = 1, #self.giftList do
            if not self:IsDrawGift(self.giftList[i]) then
                return true
            end
        end
        return false
    end
end

