--- 获取好友的module 模块是否解锁
---@param unlockModuleIds table 解锁模块数据
---@param moduleId string 解锁模块Id
function FriendComponent:GetUnlockModule(unlockModuleIds ,moduleId)
    local isUnlock = false
    local unlockModuleIds = unlockModuleIds or {}
    for index, oneModuleId in pairs(unlockModuleIds) do
        if checkInt(oneModuleId) == moduleId  then
            isUnlock = true
            break
        end
    end
    return isUnlock
end


