---给其他玩家发送pvp邀请
function FriendComponent:SendFriendPVPInvitation(friendId, friendName, waitTime)
    if isNull(friendId) or isNull(friendName) then
        return
    end
    if isNull(self.pvpUnlockLevel) then
        self.pvpUnlockLevel = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 8).num)--好友参数表中的好友切磋解锁等级
    end
    if checkNumber(playerComponent.playerDojo.level) < self.pvpUnlockLevel then--先判断自己的等级是否满足
        GameUtils.Toast(localize("_level_级开启",{_level_ = self.pvpUnlockLevel}))
        return
    end
    local friendData = self:GetFriendInfo(friendId)--再判断好友的等级是否满足
    if checkNumber(friendData.level) < self.pvpUnlockLevel then
        GameUtils.Toast(localize("对方未开启切磋"))
        return
    end
    UIRaycastBlocker:AddCondition("SendFriendPVPInvitation")

    if isNull(waitTime) then
        waitTime = self:GetPVPWaitTime()--好友参数表中的好友切磋邀请待处理时间（秒）
    end
    --需处理超时，忙碌和手动拒绝的情况，在1秒延时后如果没有收到忙碌邀请则才邀请界面
    xTry(function ()
        cs_coroutine.start(function()
            AppService:GetInstance():RequireFriendPVP(friendId)
            coroutine.yield(CS.UnityEngine.WaitForSeconds(1))
            if not AppService:GetInstance().friendIsBusy then
                UIModule.OpenDialog({id = Constants.UITypeIds.FriendInvitationSend, parameters = {
                    name = friendName,
                    time = waitTime
                }})
            else
                --GameUtils.Toast(localize("对方正在忙碌"))--飘字改到长连接收到时
                AppService:GetInstance().friendIsBusy = false
            end
            UIRaycastBlocker:RemoveCondition("SendFriendPVPInvitation")
        end)
    end, function ()
        UIRaycastBlocker:RemoveCondition("SendFriendPVPInvitation")
    end)
end

---维护好友请求的数据
---@param isAgree number  同意1 拒绝2
---@param friendId number 玩家id
---@param data table 好友数据
function FriendComponent:MaintainFriendRequestData(isAgree, friendIdList, data, isOneKey, overLimit)
    if isNull(isAgree) or isNull(friendIdList) then
        return
    end

    local dealFriendMap = {}
    for _, friendId in ipairs(friendIdList) do
        dealFriendMap[checkInt(friendId)] = true
    end

    local index = 1
    while(index <= #self.friendRequest and table.count(dealFriendMap) > 0) do
        local friendId = checkInt(self.friendRequest[index].friendId)
        if dealFriendMap[checkInt(friendId)] == true then
            table.remove(self.friendRequest, index)
            dealFriendMap[friendId] = nil
        else
            index = index + 1
        end
    end

    local hasAddFriend = false
    if checkInt(isAgree) == 1 then --同意了之后添加到好友列表
        for _, dt in ipairs(data or {}) do
            table.insert(self.friendList, dt)
            self.friendIdMap[tostring(dt.friendId)] = dt
            hasAddFriend = true
        end
    end

    if hasAddFriend then
        if overLimit then
            GameUtils.Toast(localize("好友位不足"))
        else
            GameUtils.Toast(localize("添加成功"))
        end
    elseif checkInt(isAgree) == 1 then
        GameUtils.Toast(localize("玩家好友已满"))
    end
end

