--- pk邀请结果  8002
---@param packetData any
function FriendComponent:InviteResult(packetData)
    local result = checkInt(packetData.result)
    if result == 0 then
        self:SetInviteState(true)
        -- 邀请成功
        self.invitingRoomId = packetData.roomId -- 邀请方收到房间id
        local info = self:GetFriendInfo(self.invitingFriendId)
        UIModule.OpenDialog({id = Constants.UITypeIds.FriendInvitationSend, parameters = {
            name = info.name,
            time = self:InviteWaitTime() + 5,  -- 额外加5s。为了减少出现对方踩着deadline接受邀请开始战斗了，但是这边已经超时的边际情况
        }})
    elseif result == 5 then
        -- 如果没有编队，先去编队
        GameUtils.Toast(localize("您还没有编队，请先编个队吧"))
        if not self:IsInPVPFormation() then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = Constants.SpecialQuestId.FriendPVPId, teamIndex = 1 } })
        end
    else
        GameUtils.Toast(packetData.msg)
    end
end

