--- 服务器通知开始PK    8012
function FriendComponent:EnterBattle(packetData)
    if BattleViewMgr then return end

    -- 如果已经取消邀请了，那么之后再收到进入战斗也不进入了
    -- 服务器收到取消邀请的消息以后，会通知对方也退出战斗
    if not self.invitingPK then end

    local args = {
        server = packetData.server,
        pvpMode = Constants.PVPMode.Friend,
        roomId = packetData.roomId,
    }

    local params = {
        oppoId = self.invitingFriendId,
        mainTeam = packetData.mainTeamSet.cardInfo,
        mainTeamInfo = packetData.mainPlayerInfo,
        mainTeamPower = packetData.mainTeamSet.combatValue,
        subTeam = packetData.subTeamSet.cardInfo,
        subTeamInfo = packetData.subPlayerInfo,
        subTeamPower = packetData.subTeamSet.combatValue,
    }

    FightPreWarMgr:GetInstance():InitPVPParams(args)
    GameUtils.OpenLoadingPanel(UIArgs(Constants.UITypeIds.BattleScene, params), nil, Constants.LoadingType.PVPFriend)
end

--- 服务器通知PK取消    8014
---@param packetData any
function FriendComponent:CancelBattle(packetData)
    if BattleViewMgr then
        -- 如果已经开始进战斗了，退出战斗
        GameUtils.Toast(localize("对方取消了PK"))
        GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome)
    else
        -- 触发取消邀请
        GameUtils.Toast(localize("对方取消了邀请"))
        Events.Broadcast(Constants.EventNames.FriendPVPPromptBeCancelled, true)
    end
end

function FriendComponent:HasPVPTeam()
    ---@type TeamComponent
    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local team = teamComponent:GetTeamByQuestId(Constants.SpecialQuestId.FriendPVPId, 1)

    if isNull(team) then
        return false
    end
    
    for i, cardInfo in ipairs(team) do
        if checkNumber(cardInfo.cardId) > 0 then
            return true
        end
    end

    return false
end

function FriendComponent:IsInPVPFormation()
    local UIModule = CS.Engine.UI.UIModule
    local dialogs = UIModule.CurrentScreen.dialogs
    local dialogsCount = dialogs.Count

    for i = 0, dialogs.Count - 1 do
        local dialog = dialogs[i]
        local dialogId = dialog.Argument.id
        if (dialogId == Constants.UITypeIds.UIFightTeamChoose and dialog.Env.curLevelId == Constants.SpecialQuestId.FriendPVPId)
        or (dialogId == Constants.UITypeIds.UIFightTeamCardChoose and dialog.Env._curLevelId == Constants.SpecialQuestId.FriendPVPId) then
            return true
        end
    end

    return false
end

function FriendComponent:InviteWaitTime()
    return checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 6).num)
end

return FriendComponent